function short(n, u) { u=0; n=int(n<0?0:n); while(n>=1000 && u<5) { n=int(n/1000); u++ } return sprintf("%d%s", n%10000, u?substr(" KMGTP",u+1,1):"") }
/^body\.(response\.)?usage\./ && $2 ~ /^[0-9]+$/ { k=$1; sub(/:$/,"",k); sub(/^.*\./,"",k); v[k]=$2; seen=1 }
END {
  if(!seen) exit
  input=v["input_tokens"]; out=v["output_tokens"]; cached=v["cached_tokens"]; written=v["cache_write_tokens"]; thinking=v["reasoning_tokens"]
  hit=input>0?int(cached*100/input):0; b=int(hit*7/100); if(b<0)b=0; if(b>6)b=6
  split("▁ ▂ ▃ ▄ ▅ ▆ ▇",blocks," ")
  printf "::stats::✥%s%s%s::%d in, %d cached (%d%%)", short(out), (cached>0?blocks[b+1]:"_"), short(input), input, cached, hit
  if(written>0) printf ", %d written",written
  printf ", %d out",out
  if(thinking>0) printf " (%d thinking)",thinking
  printf "\n"
}

upload:
# Emit MIME data:MIME;base64,BYTES NAME 
p=${1% (*} h=${1##* (} h=${h%)}; n=${p##*/}
case $n in
  *.jpeg|*.jpg) m=image/jpeg ;; *.png) m=image/png ;; *.gif) m=image/gif ;;
  *.webp) m=image/webp ;; *.pdf) m=application/pdf ;;
  *) echo "upload: no type for $n" >&2; exit 1 ;;
esac
case $p in /*) f=$p ;; *) f=$M8_MOB_ST8_DIR/$p ;; esac
stamp() { stat -c '%d:%i:%s:%Y:%Z' -- "$1" 2>/dev/null || stat -f '%d:%i:%z:%m:%c' -- "$1"; }
before=$(stamp "$f") || exit
[ "$({ sha256sum 2>/dev/null || shasum -a 256; } <"$f" | cut -c1-64)" = "$h" ] || { echo "upload: $p is not the file linked" >&2; exit 1; }
printf '%s data:%s;base64,' $m $m; base64 <"$f" | tr -d '\n'; printf ' %s' "$n"
after=$(stamp "$f") || exit
[ "$before" = "$after" ] || { echo "upload: $p changed while encoding" >&2; exit 1; }
